# Simple hypothesis: 1s adjacent to ANY 9 become 3
def transform_simple(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                # Check 4 neighbors
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == 9:
                            result[r][c] = 3
                            break
    return result

