def find_all_components_8way(grid, val):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    all_comps = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == val and not visited[r][c]:
                comp = []
                q = [(r,c)]
                visited[r][c] = True
                while q:
                    cr, cc = q.pop()
                    comp.append((cr, cc))
                    # 8 neighbors
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                                if grid[nr][nc] == val:
                                    visited[nr][nc] = True
                                    q.append((nr, nc))
                all_comps.append(comp)
    return all_comps

