from collections import deque

def flood_fill_trapping(grid, start_r, start_c, obstacle_coords):
    """Check if starting cell can reach any edge without hitting obstacles."""
    rows = len(grid)
    cols = len(grid[0])

    # BFS from start, avoiding obstacles and out of bounds
    q = deque([(start_r, start_c)])
    visited = {(start_r, start_c)}

    while q:
        r, c = q.popleft()
        # Check if at edge
        if r == 0 or r == rows-1 or c == 0 or c == cols-1:
            return True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) not in visited:
                        val = grid[nr][nc]
                        # Can pass through 1s, cannot pass through obstacles or 9s
                        if val != 1 and (nr, nc) not in obstacle_coords:
                            visited.add((nr, nc))
                            q.append((nr, nc))
    return False

