def find_connected_component_4way(grid, r, c, block_val=9):
    """Find 4-way connected component"""
    h, w = len(grid), len(grid[0])
    visited = set()
    stack = [(r, c)]

    while stack:
        curr_r, curr_c = stack.pop()
        if (curr_r, curr_c) in visited:
            continue
        visited.add((curr_r, curr_c))

        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == grid[curr_r][curr_c] != block_val:
                    if grid[nr][nc] not in [x[0] for x in visited if isinstance(x, tuple)]:
                        # Just check value
                        if grid[nr][nc] != block_val and (nr, nc) not in visited:
                            stack.append((nr, nc))
    return visited

# Actually simpler - flood fill through same values
def get_component_of(r, c, grid):
    h, w = len(grid), len(grid[0])
    val = grid[r][c]
    visited = set()
    stack = [(r, c)]

    while stack:
        rr, cc = stack.pop()
        if (rr, cc) in visited:
            continue
        visited.add((rr, cc))

        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = rr + dr, cc + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == val and (nr, nc) not in visited:
                    stack.append((nr, nc))
    return visited

